def test_<scenario_name>(self, page: Page, base_url: str, fixture_name: dict): """FN:test_<scenario_name> - Verify <expected outcome>.""" # Arrange - Set up page objects page_obj = <Page>Page(page)
# Act - Perform user actions from spec steps page_obj.navigate() page_obj.<action_method>(<parameters>)
# Assert - Verify expected results expect(page).to_have_url("<expected_url>") expect(page_obj.<element>).to_be_visible()

class <Page>Page:
    """FN:<Page>Page - Page Object for <Page Name>."""

    def __init__(self, page: Page):
        """FN:__init__ - Initialize with Page instance."""
        self.page = page

    @property
    def <element_name>(self):
        """FN:<element_name> - Returns <element> locator."""
        return self.page.get_by_role("<role>", name="<name>")

    def <action>(self, <parameters>):
        """FN:<action> - Perform <action> on page."""
        self.<element_name>.fill(<parameters>)
